import{_ as e,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"1988年 · 买入值得持有的公司","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1988年.md","filePath":"05_quotes/by-year/1988年.md"}'),r={name:"05_quotes/by-year/1988年.md"};function u(q,t,s,c,h,i){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="_1988年-·-买入值得持有的公司" tabindex="-1">1988年 · 买入值得持有的公司 <a class="header-anchor" href="#_1988年-·-买入值得持有的公司" aria-label="Permalink to &quot;1988年 · 买入值得持有的公司&quot;">​</a></h1><blockquote><p>&quot;我们买了杰出企业杰出管理层，我们最喜欢持有期限就是永远。&quot;——巴菲特（58岁）</p></blockquote><p>本页收录1988年致股东信中的经典语录。巴菲特在这一年完成了传奇投资——买入可口可乐，并系统阐述了为什么集中持有少数真正理解的好公司，才是真正的投资之道。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;我们买了杰出企业杰出管理层，我们最喜欢持有期限就是永远。我们正好相反，表现好赶紧卖赚利润，表现差死拿着，就像Peter Lynch说的，这就是掐花浇野草。&quot;</p></blockquote><blockquote><p>&quot;我们找到出色business关系太罕见太珍贵，我们不想换来换去，已经和喜欢欣赏的人做生意，为什么要换给不认识不喜欢的，没必要。&quot;</p></blockquote><blockquote><p>&quot;我五六岁就喝可口可乐，1936年我就买可口可乐股票，五分钱两杯，我买过来零售五分钱一杯卖，赚一分钱，那时候我就发现可口可乐消费者吸引力太强，商业潜力太大。&quot;</p></blockquote><blockquote><p>&quot;我们三大永久持仓，管理层热爱生意，像所有者一样思考，诚信能力都够，我们太幸运了。&quot;</p></blockquote><blockquote><p>&quot;平庸CEO保住位置比平庸秘书容易，秘书工作好说，标准清楚，不行马上走；CEO不行，标准模糊，就算错了，也总能找到借口解释，董事会也不会批评，老板错了没人批评CEO，所以坏事一直持续。&quot;</p></blockquote><blockquote><p>&quot;我们买股票帮助首都城市/ABC融资35亿美元收购美国广播公司，我们一点不担心，生孩子不可能一个月让九个女人怀上，所以急不了。&quot;</p></blockquote><blockquote><p>&quot;我们不喜欢长期债券，我们不相信美元长期购买力稳定，所以我们不碰，除非价格特别错杀，才会买一点。&quot;</p></blockquote><blockquote><p>&quot;我们投资风格就是懒，六大重仓，一股没卖；买了富国银行，占到接近10%，美联储批准才能买这么多。&quot;</p></blockquote><blockquote><p>&quot;我们股息政策很简单，过去二十年没分红，现在净资产大概三十亿，我们积累资本，过去回报率一直超过平均，所以我们不分红比分红股东拿到更多价值，股东拿到资本利得税还能推迟。&quot;</p></blockquote><blockquote><p>&quot;B夫人说，&#39;年龄永远比我小十岁&#39;。Dillard百货进奥马哈宣布不卖家具，说&#39;我们不想和B夫人竞争&#39;。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1988年伯克希尔净值增长5.69亿美元，增幅20.0%，过去二十四年复合增长率23.0%。巴菲特在这一年买入了7亿美元可口可乐股票，并收购了Borsheim&#39;s珠宝店（又一位B夫人家族成员Ike Friedman）。GEICO继续保持强劲增长，保险承保综合成本率改善至104。巴菲特宣布了七个运营企业（七圣人）平均ROE高达67%的惊人记录。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1988年-翻译-·-01-letters-1988年-核心总结-·-01-letters-1988年-思维导图" tabindex="-1"><a href="/01_letters/1988年/翻译.html">01_letters/1988年/翻译</a> · <a href="/01_letters/1988年/核心总结.html">01_letters/1988年/核心总结</a> · <a href="/01_letters/1988年/思维导图.html">01_letters/1988年/思维导图</a> <a class="header-anchor" href="#_01-letters-1988年-翻译-·-01-letters-1988年-核心总结-·-01-letters-1988年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1988年/翻译]] · [[→ 核心总结|01_letters/1988年/核心总结]] · [[→ 思维导图|01_letters/1988年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1988年/翻译.html">/01_letters/1988年/翻译</a></li></ul>',23)])])}const n=e(r,[["render",u]]);export{b as __pageData,n as default};
